<div class="page-head"><div><h1>Plan a trip</h1></div></div>
<form method="get" class="filters"><div class="field"><label for="wsel">Leaving from</label><select id="wsel" name="warehouse_id" data-autosubmit><?php foreach ($warehouses as $w): ?><option value="<?= $w['id'] ?>" <?= (int) $w['id'] === $wh ? 'selected' : '' ?>><?= esc($w['code'] . ' ' . $w['name']) ?></option><?php endforeach ?></select></div></form>
