<?php foreach ($shipments as $s): ?><tr><td><input type="checkbox" name="shipments[]" value="<?= $s['id'] ?>" aria-label="Carry <?= esc($s['number'], 'attr') ?>"></td><td><?= esc($s['number']) ?> <span class="muted small"><?= esc($s['order_no']) ?></span></td><td><?= esc($s['customer']) ?></td><td><?= esc($s['town']) ?></td><td><?= badge($s['status']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<h2>Transfers</h2><?php if (! $transfers): ?><div class="panel empty">No transfers waiting at this warehouse.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th></th><th>Transfer</th><th>To</th><th>Status</th></tr></thead><tbody>
